/**
 * Batch 7 — ~110 verified India Quiz questions.
 * 10 per category × 11 categories.
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string; categoryId: string; text: string;
  options: [string, string, string, string]; correctIndex: number;
  explanation: string; source: string; difficulty: 'easy'|'medium'|'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk (10) ═══
  { slug: 'gk-india-largest-stadium-name', categoryId: 'cat-gk', text: 'The Narendra Modi Stadium in Ahmedabad is the world\'s largest cricket stadium by capacity. How many spectators can it seat?', options: ['About 75,000', 'About 100,000', 'About 132,000', 'About 150,000'], correctIndex: 2, explanation: 'The Narendra Modi Stadium (formerly Motera Stadium) in Ahmedabad, Gujarat, has a seating capacity of approximately 132,000, making it the world\'s largest cricket stadium. It was inaugurated in February 2021. The previous record holder was the Melbourne Cricket Ground (~100,024).', source: 'BCCI / Gujarat Cricket Association', difficulty: 'medium' },
  { slug: 'gk-india-first-5g-city', categoryId: 'cat-gk', text: '5G services were first launched in India in which cities on 1 October 2022?', options: ['Delhi and Mumbai only', 'Mumbai, Delhi, Kolkata, Chennai, and Varanasi', 'Bengaluru and Hyderabad only', 'All Tier-1 cities simultaneously'], correctIndex: 1, explanation: '5G services were first launched on 1 October 2022 by PM Modi at the India Mobile Congress in Delhi. The initial rollout covered Mumbai, Delhi, Kolkata, Chennai, and Varanasi. Airtel and Jio were the first operators. India\'s 5G rollout was among the fastest globally, reaching 10,000+ cities/towns within one year.', source: 'Department of Telecommunications / TRAI', difficulty: 'medium' },
  { slug: 'gk-india-longest-sea-bridge', categoryId: 'cat-gk', text: 'Which is India\'s longest sea bridge (over water)?', options: ['Bandra-Worli Sea Link (Mumbai)', 'Atal Setu (Mumbai Trans Harbour Link)', 'Vembanad Rail Bridge (Kerala)', 'Pamban Bridge (Tamil Nadu)'], correctIndex: 1, explanation: 'The Atal Setu (Mumbai Trans Harbour Link, MTHL) is India\'s longest sea bridge at 21.8 km, inaugurated on 12 January 2024. It connects Sewri (Mumbai) to Nhava Sheva (Navi Mumbai). The Bandra-Worli Sea Link is 5.6 km. The Pamban Bridge connects Rameswaram island to the mainland.', source: 'Ministry of Road Transport and Highways / NHAI', difficulty: 'medium' },
  { slug: 'gk-india-national-waterway-one', categoryId: 'cat-gk', text: 'National Waterway 1 (NW-1), India\'s longest navigable waterway, flows along which river?', options: ['Brahmaputra', 'Ganga (from Allahabad to Haldia)', 'Godavari', 'Mahanadi'], correctIndex: 1, explanation: 'National Waterway 1 (NW-1) is on the Ganga River, stretching 1,620 km from Allahabad (Prayagraj) to Haldia (West Bengal). It was declared a National Waterway in 1986. The Jal Marg Vikas Project aims to develop NW-1 for commercial navigation, reducing logistics costs and pollution.', source: 'Ministry of Ports, Shipping and Waterways / Inland Waterways Authority of India', difficulty: 'medium' },
  { slug: 'gk-india-digital-india-launch', categoryId: 'cat-gk', text: 'The "Digital India" campaign was launched on which date?', options: ['1 July 2014', '1 July 2015', '15 August 2015', '2 October 2015'], correctIndex: 1, explanation: 'Digital India was launched on 1 July 2015. It aims to transform India into a digitally empowered society and knowledge economy. Key pillars include: broadband highways, universal access to phones, e-governance, e-Kranti (electronic delivery of services), information for all, IT for jobs, and early harvest programmes.', source: 'Ministry of Electronics and IT (MeitY)', difficulty: 'medium' },
  { slug: 'gk-india-largest-solar-park-world', categoryId: 'cat-gk', text: 'Which solar park in India is one of the world\'s largest by installed capacity?', options: ['Bhadla Solar Park (Rajasthan)', 'Kurnool Solar Park (Andhra Pradesh)', 'Rewa Solar Park (Madhya Pradesh)', 'Pavagada Solar Park (Karnataka)'], correctIndex: 0, explanation: 'Bhadla Solar Park in Jodhpur district, Rajasthan, is one of the world\'s largest solar parks with a total capacity of 2,245 MW. It covers about 14,000 acres in the Thar Desert. It was developed by RRECL (Rajasthan Renewable Energy Corporation Ltd). India\'s total installed solar capacity is approximately 73 GW (as of 2024).', source: 'Ministry of New and Renewable Energy (MNRE) / RRECL', difficulty: 'medium' },
  { slug: 'gk-india-first-underwater-metro', categoryId: 'cat-gk', text: 'India\'s first underwater metro tunnel runs under which river?', options: ['Yamuna (Delhi)', 'Hooghly (Kolkata)', 'Ganga (Patna)', 'Sabarmati (Ahmedabad)'], correctIndex: 1, explanation: 'India\'s first underwater metro tunnel runs under the Hooghly River in Kolkata, as part of the East-West Metro corridor. The 520-metre tunnel was completed in 2017 and the line became operational in 2020-2024 (partial). It connects Howrah Maidan to Salt Lake (Sector V), with Howrah Maidan being the deepest metro station in India.', source: 'Kolkata Metro Rail Corporation (KMRC) / Ministry of Housing and Urban Affairs', difficulty: 'medium' },
  { slug: 'gk-india-longest-railway-platform', categoryId: 'cat-gk', text: 'Which Indian railway station has the world\'s longest railway platform?', options: ['New Delhi Railway Station', 'Gorakhpur Junction', 'Hubbali Railway Station (Karnataka)', 'Howrah Junction'], correctIndex: 2, explanation: 'Hubbali (Hubli) Railway Station in Karnataka has the world\'s longest railway platform at 1,505 metres, inaugurated in February 2023. It surpassed Gorakhpur Junction (1,366 m, inaugurated in 2013). Both are on Indian Railways\' network. Hubbali is a major junction in the South Western Railway zone.', source: 'Indian Railways / South Western Railway', difficulty: 'medium' },
  { slug: 'gk-india-statue-of-unity-world-rank', categoryId: 'cat-gk', text: 'The Statue of Unity in Gujarat is the world\'s tallest statue. How tall is it?', options: ['128 m', '153 m', '182 m', '200 m'], correctIndex: 2, explanation: 'The Statue of Unity is 182 m (597 ft) tall, making it the world\'s tallest statue. Located at Kevadia, Gujarat, it depicts Sardar Vallabhbhai Patel. It was inaugurated on 31 October 2018 (Patel\'s birth anniversary). The second tallest is the Spring Temple Buddha (128 m) in China, and third is the Laykyun Sekkya Buddha (116 m) in Myanmar.', source: 'Ministry of Home Affairs / Gujarat Tourism / Sardar Sarovar Narmada Nigam', difficulty: 'easy' },
  { slug: 'gk-india-national-anthem-duration-full', categoryId: 'cat-gk', text: 'The full version of India\'s national anthem "Jana Gana Mana" takes approximately how long to play?', options: ['30 seconds', '52 seconds', '1 minute 30 seconds', '2 minutes'], correctIndex: 1, explanation: 'The full version of "Jana Gana Mana" takes approximately 52 seconds to play. A shorter version of about 20 seconds (first and last lines) is used on certain occasions. The anthem was composed by Rabindranath Tagore in Bengali (originally "Bharoto Bhagyo Bidhata") and adopted on 24 January 1950.', source: 'Government of India national symbols / Ministry of Home Affairs', difficulty: 'medium' },

  // ═══ cat-history (10) ═══
  { slug: 'hist-indus-valley-trade-mesopotamia', categoryId: 'cat-history', text: 'Archaeological evidence suggests that the Indus Valley Civilisation had trade links with which contemporary civilisation?', options: ['Ancient Egypt', 'Mesopotamia (Sumerian civilisation)', 'Minoan Crete', 'Ancient China'], correctIndex: 1, explanation: 'The Indus Valley Civilisation had extensive trade links with Mesopotamia (Sumerian civilisation, c. 2600-1900 BCE). Indus seals, beads, and copper objects have been found at Mesopotamian sites like Ur and Nineveh. Mesopotamian texts refer to "Meluhha" — believed to be the Indus Valley. Trade was conducted via sea routes through the Persian Gulf.', source: 'Archaeological Survey of India / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-gupta-empire-navaratna', categoryId: 'cat-history', text: 'The "Navaratnas" (Nine Gems) — a council of nine extraordinary scholars — were associated with whose court?', options: ['Ashoka\'s court', 'Chandragupta Vikramaditya II\'s court', 'Harshavardhana\'s court', 'Krishnadevaraya\'s court'], correctIndex: 1, explanation: 'The "Navaratnas" (Nine Gems) are traditionally associated with the court of Chandragupta Vikramaditya II (r. c. 380-415 CE) of the Gupta Empire. The nine included Kalidasa (poet), Varahamihira (astronomer), Aryabhata (mathematician — though historically associated with the Guptas, his presence in the Navaratnas is debated), and others. The concept was later applied to Akbar\'s court.', source: 'Indian Council of Historical Research / Sahitya Akademi', difficulty: 'hard' },
  { slug: 'hist-delhi-sultanate-tughlaq-capital-shift', categoryId: 'cat-history', text: 'Muhammad bin Tughlaq is infamous for shifting the capital of the Delhi Sultanate from Delhi to which city in 1327?', options: ['Agra', 'Devagiri (Daulatabad)', 'Lahore', 'Jaunpur'], correctIndex: 1, explanation: 'Muhammad bin Tughlaq shifted the capital from Delhi to Devagiri (renamed Daulatabad, in present-day Maharashtra) in 1327. He forced the entire population of Delhi to migrate. The move was a disaster — many died en route, and the capital was shifted back to Delhi within a few years. This is considered one of his most controversial administrative decisions.', source: 'Indian Council of Historical Research / Tarikh-i-Firoz Shahi', difficulty: 'medium' },
  { slug: 'hist-akbar-din-ilahi-year', categoryId: 'cat-history', text: 'Emperor Akbar promulgated the "Din-i-Ilahi" (Divine Faith) in which year?', options: ['1575', '1582', '1590', '1601'], correctIndex: 1, explanation: 'Akbar promulgated the "Din-i-Ilahi" in 1582. It was a syncretic religious path combining elements of Islam, Hinduism, Zoroastrianism, Christianity, and Jainism, aimed at fostering communal harmony. Only about 18 people are believed to have joined, including Birbal. It was not a mass religion and declined after Akbar\'s death.', source: 'Indian Council of Historical Research / Abul Fazl\'s Akbarnama', difficulty: 'hard' },
  { slug: 'hist-1857-rebellion-nana-saheb', categoryId: 'cat-history', text: 'Nana Saheb, a key leader of the 1857 revolt, was the adopted son of which Maratha Peshwa?', options: ['Peshwa Bajirao I', 'Peshwa Bajirao II', 'Peshwa Madhavrao I', 'Peshwa Balaji Bajirao'], correctIndex: 1, explanation: 'Nana Saheb (born Dhondu Pant) was the adopted son of Peshwa Bajirao II. After Bajirao II\'s death, the British refused to recognise Nana Saheb\'s adoption and stopped his pension, citing the Doctrine of Lapse. This was one of the grievances that led Nana Saheb to join the 1857 revolt at Kanpur. He disappeared after the revolt\'s suppression.', source: 'National Archives of India / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-inc-lucknow-pact-1916', categoryId: 'cat-history', text: 'The Lucknow Pact of 1916 was an agreement between which two political parties?', options: ['Indian National Congress and the British government', 'Indian National Congress and the Muslim League', 'Muslim League and the Hindu Mahasabha', 'Indian National Congress and the Swaraj Party'], correctIndex: 1, explanation: 'The Lucknow Pact (1916) was an agreement between the Indian National Congress and the Muslim League, reached during their simultaneous annual sessions in Lucknow. The Congress accepted separate electorates for Muslims, and both parties agreed on a common demand for self-government. It was signed at a time when both parties were led by moderate leaders.', source: 'Indian National Congress Archives / National Archives of India', difficulty: 'medium' },
  { slug: 'hist-mountbatten-plan-date', categoryId: 'cat-history', text: 'The Mountbatten Plan (also called the 3 June Plan) for the Partition of India was announced on which date?', options: ['3 June 1947', '15 August 1947', '20 February 1947', '4 July 1947'], correctIndex: 0, explanation: 'The Mountbatten Plan was announced on 3 June 1947. It proposed the partition of British India into two dominions: India and Pakistan. The plan was accepted by the Congress and the Muslim League. The Indian Independence Act, 1947 was passed by the British Parliament on 18 July 1947, implementing the plan.', source: 'National Archives of India / Indian Independence Act, 1947', difficulty: 'medium' },
  { slug: 'hist-princely-state-hyderabad-integration', categoryId: 'cat-history', text: 'The integration of the princely state of Hyderabad into India was achieved through which military operation in 1948?', options: ['Operation Vijay', 'Operation Polo (Police Action)', 'Operation Steeplechase', 'Operation Blue Star'], correctIndex: 1, explanation: 'Operation Polo (also called "Police Action") was the Indian military operation in September 1948 that integrated the princely state of Hyderabad into the Indian Union. The Nizam of Hyderabad, Osman Ali Khan, had refused to accede to either India or Pakistan. Indian forces entered Hyderabad on 13 September 1948, and the Nizam surrendered on 17 September.', source: 'Ministry of Home Affairs / Indian Army', difficulty: 'medium' },
  { slug: 'hist-princely-state-junagadh-referendum', categoryId: 'cat-history', text: 'The princely state of Junagadh (in present-day Gujarat) acceded to India after what process in 1948?', options: ['Military operation', 'A referendum in which the majority voted to join India', 'The Nawab voluntarily joined India', 'The British government decided it'], correctIndex: 1, explanation: 'Junagadh acceded to India after a referendum in February 1948, in which approximately 99.5% of voters chose to join India. The Nawab of Junagadh had initially acceded to Pakistan in September 1947, but the predominantly Hindu population and the state\'s geographical separation from Pakistan led to the referendum.', source: 'Ministry of Home Affairs / Election Commission of India', difficulty: 'hard' },
  { slug: 'hist-buddhist-stupa-sanchi-origin', categoryId: 'cat-history', text: 'The Great Stupa at Sanchi was originally built by Emperor Ashoka in the 3rd century BCE. Its famous gateways (toranas) were added during which period?', options: ['Maurya period (3rd century BCE)', 'Sunga period (1st century BCE)', 'Gupta period (4th century CE)', 'Mughal period (16th century)'], correctIndex: 1, explanation: 'The four ornate toranas (gateways) of the Great Stupa at Sanchi were added during the Sunga period (c. 1st century BCE), under the patronage of the Satavahanas. The gateways feature intricate carvings depicting scenes from the Buddha\'s life, Jataka tales, and contemporary society. Sanchi is a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },

  // ═══ cat-geography (10) ═══
  { slug: 'geo-india-river-kaveri-origin', categoryId: 'cat-geography', text: 'The Kaveri (Cauvery) river originates in which location?', options: ['Talakaveri (Coorg/Kodagu, Karnataka)', 'BR Hills (Karnataka)', 'Nilgiri Hills (Tamil Nadu)', 'Brahmagiri Hills (Kerala)'], correctIndex: 0, explanation: 'The Kaveri originates at Talakaveri in the Brahmagiri Hills of the Western Ghats in Kodagu (Coorg) district, Karnataka. It flows about 805 km through Karnataka and Tamil Nadu before emptying into the Bay of Bengal at Poompuhar. The Kaveri is considered sacred in South India and is the subject of a long-running water-sharing dispute between Karnataka and Tamil Nadu.', source: 'Ministry of Water Resources / Central Water Commission', difficulty: 'medium' },
  { slug: 'geo-india-narmada-rift-valley', categoryId: 'cat-geography', text: 'The Narmada river flows through a rift valley between which two mountain ranges?', options: ['Vindhya and Satpura ranges', 'Aravalli and Vindhya ranges', 'Western Ghats and Eastern Ghats', 'Pir Panjal and Zanskar ranges'], correctIndex: 0, explanation: 'The Narmada flows westward through a rift valley between the Vindhya Range (to the north) and the Satpura Range (to the south). The rift valley was formed by geological faulting. The Narmada is one of the few major Indian rivers that flows westward. It is about 1,312 km long and drains into the Arabian Sea.', source: 'Geological Survey of India / Ministry of Water Resources', difficulty: 'medium' },
  { slug: 'geo-india-highest-waterfall-tier-list', categoryId: 'cat-geography', text: 'Which is the highest waterfall in India (by total drop height)?', options: ['Jog Falls (Karnataka)', 'Kunchikal Falls (Karnataka)', 'Dudhsagar Falls (Goa-Karnataka)', 'Athirappilly Falls (Kerala)'], correctIndex: 1, explanation: 'Kunchikal Falls in Karnataka is the tallest waterfall in India with a total height of about 455 m (1,493 ft). It is a tiered waterfall on the Varahi River in the Western Ghats. Jog Falls ( Karnataka, ~253 m) is the second-highest plunge waterfall. However, Kunchikal\'s flow has reduced due to a dam upstream.', source: 'Geological Survey of India', difficulty: 'hard' },
  { slug: 'geo-india-eastern-ghats-vs-western', categoryId: 'cat-geography', text: 'How do the Eastern Ghats differ from the Western Ghats in terms of continuity and height?', options: ['The Eastern Ghats are taller and more continuous', 'The Eastern Ghats are lower, older, and discontinuous (eroded by rivers)', 'The Eastern Ghats are younger and taller', 'Both ranges are identical in height and continuity'], correctIndex: 1, explanation: 'The Eastern Ghats are lower, older, and discontinuous compared to the Western Ghats. They have been eroded by rivers like the Godavari, Krishna, and Mahanadi, creating gaps. The Western Ghats are taller, more continuous, and geologically younger — they are a UNESCO World Heritage Site and one of the world\'s biodiversity hotspots.', source: 'Geological Survey of India / UNESCO World Heritage List', difficulty: 'medium' },
  { slug: 'geo-india-soil-type-alluvial-percentage', categoryId: 'cat-geography', text: 'Alluvial soil is the most widespread soil type in India, covering approximately what percentage of the total area?', options: ['About 15%', 'About 25%', 'About 43%', 'About 60%'], correctIndex: 2, explanation: 'Alluvial soil covers approximately 43% of India\'s total land area. It is the most widespread soil type, found primarily in the Indo-Gangetic plains, river deltas, and coastal plains. Alluvial soils are highly fertile and support India\'s major agricultural production. Other major soil types: black soil (15%), red soil (18.5%), laterite soil (4.5%).', source: 'Indian Council of Agricultural Research (ICAR) / National Bureau of Soil Survey', difficulty: 'medium' },
  { slug: 'geo-india-monsoon-revival-mumbai', categoryId: 'cat-geography', text: 'The southwest monsoon arrives in Mumbai (west coast) and Kolkata (east) in approximately which week of June?', options: ['First week of June (1-7 June)', 'Second week of June (8-15 June)', 'Third week of June', 'Fourth week of June'], correctIndex: 0, explanation: 'The southwest monsoon typically arrives in Mumbai around 10 June and in Kolkata around 8-11 June (first to second week of June). The monsoon first reaches the Kerala coast around 1 June, then progresses northward. It covers all of India by approximately 15 July. The retreat (northeast monsoon) begins in September from northwest India.', source: 'India Meteorological Department (IMD)', difficulty: 'medium' },
  { slug: 'geo-india-largest-coral-reef-gulf-mannar', categoryId: 'cat-geography', text: 'The Gulf of Mannar, which contains India\'s richest coral reef biodiversity, lies between which two land masses?', options: ['India and Sri Lanka', 'India and Bangladesh', 'India and Myanmar', 'India and Maldives'], correctIndex: 0, explanation: 'The Gulf of Mannar lies between the southeastern coast of India (Tamil Nadu) and the northwestern coast of Sri Lanka. It contains India\'s first marine biosphere reserve — the Gulf of Mannar Marine National Park (designated in 1986) with 21 islands, 3,600+ species of flora and fauna, and extensive coral reefs. It is also associated with the "Ram Setu" (Adam\'s Bridge).', source: 'Ministry of Environment, Forest and Climate Change / Gulf of Mannar Biosphere Reserve Trust', difficulty: 'medium' },
  { slug: 'geo-india-theri-desert-cold-spiti', categoryId: 'cat-geography', text: 'Spiti Valley, a cold desert region in India, is located in which state?', options: ['Ladakh', 'Himachal Pradesh', 'Uttarakhand', 'Sikkim'], correctIndex: 1, explanation: 'Spiti Valley is a cold desert located in the Lahaul and Spiti district of Himachal Pradesh. It lies in the Trans-Himalayan region, at an average altitude of about 4,270 m (12,500 ft). Spiti receives very little precipitation (less than 170 mm annually) and has extreme temperatures. It is known for its Buddhist monasteries (Key, Tabo, Dhankar) and unique landscapes.', source: 'Geological Survey of India / Himachal Pradesh Tourism', difficulty: 'medium' },
  { slug: 'geo-india-longest-coastline-state-gujarat', categoryId: 'cat-geography', text: 'Gujarat has the longest coastline among Indian states. Approximately how long is it?', options: ['About 1,000 km', 'About 1,600 km', 'About 2,500 km', 'About 3,500 km'], correctIndex: 1, explanation: 'Gujarat has the longest coastline among Indian states, approximately 1,600 km (including island territories). Andhra Pradesh has the second-longest coastline (~974 km), followed by Tamil Nadu (~907 km). Gujarat\'s coastline features the Gulf of Kutch and the Gulf of Khambhat, and includes major ports like Kandla and Mundra.', source: 'Ministry of Home Affairs / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-andaman-nicobar-distance-myanmar', categoryId: 'cat-geography', text: 'The Andaman & Nicobar Islands are geographically closer to which country than to mainland India?', options: ['Sri Lanka', 'Myanmar', 'Thailand', 'Indonesia'], correctIndex: 1, explanation: 'The Andaman & Nicobar Islands are geographically closer to Myanmar than to mainland India. The northernmost point of the Andamans (Landfall Island) is about 190 km from Myanmar\'s coast. Port Blair (the capital) is about 1,200 km from Chennai (mainland India). The southernmost point (Indira Point in the Nicobars) is about 150 km from Sumatra, Indonesia.', source: 'Andaman & Nicobar Administration / Survey of India', difficulty: 'medium' },

  // ═══ cat-civics (10) ═══
  { slug: 'civ-const-constituent-assembly-first-meeting', categoryId: 'cat-civics', text: 'The Constituent Assembly of India held its first meeting on which date?', options: ['9 December 1946', '15 August 1947', '26 January 1950', '26 November 1949'], correctIndex: 0, explanation: 'The Constituent Assembly held its first meeting on 9 December 1946 in the Constitution Hall (now Parliament House), New Delhi. Dr. Sachchidananda Sinha was the first temporary president. Dr. Rajendra Prasad was later elected as the permanent president. The Assembly initially had 389 members (later reduced to 299 after partition).', source: 'Parliament of India / Constituent Assembly Debates', difficulty: 'medium' },
  { slug: 'civ-const-objectives-resolution-date', categoryId: 'cat-civics', text: 'The "Objectives Resolution" — which outlined the philosophy of the Indian Constitution — was moved by whom and on which date?', options: ['Mahatma Gandhi, 9 December 1946', 'Jawaharlal Nehru, 13 December 1946', 'Dr. B.R. Ambedkar, 22 January 1947', 'Sardar Patel, 29 August 1947'], correctIndex: 1, explanation: 'The "Objectives Resolution" was moved by Jawaharlal Nehru on 13 December 1946 in the Constituent Assembly. It outlined the principles of the future Constitution: justice, liberty, equality, and fraternity. The resolution was adopted on 22 January 1947. Its ideals were later reflected in the Preamble of the Constitution.', source: 'Constituent Assembly Debates / Parliament of India', difficulty: 'hard' },
  { slug: 'civ-const-fundamental-rights-suspended-emergency', categoryId: 'cat-civics', text: 'During the National Emergency (1975-77), which Fundamental Right could NOT be suspended?', options: ['Right to Equality (Article 14)', 'Right to Freedom of Speech (Article 19)', 'Right to Life and Personal Liberty (Article 21)', 'Right against Exploitation (Article 23)'], correctIndex: 2, explanation: 'During the National Emergency of 1975-77, the Right to Life and Personal Liberty (Article 21) could not be suspended. The 44th Amendment (1978) made Articles 20 and 21 non-suspendable even during an Emergency. Previously, the 38th Amendment (1975) had allowed the suspension of Article 19 during Emergency, and the 42nd Amendment (1976) had made Article 21 suspendable — both reversed by the 44th Amendment.', source: 'Constitution of India, Articles 20, 21, 359 / 44th Amendment Act, 1978', difficulty: 'hard' },
  { slug: 'civ-lok-sabha-first-election-year', categoryId: 'cat-civics', text: 'The first general elections to the Lok Sabha were held in which year?', options: ['1947', '1950', '1951-52', '1955'], correctIndex: 2, explanation: 'India\'s first general elections were held from 25 October 1951 to 21 February 1952. Approximately 173 million voters participated (about 45% turnout). The Indian National Congress won 364 of 489 seats. Jawaharlal Nehru became the first elected Prime Minister. Sukumar Sen was the Chief Election Commissioner who conducted the elections.', source: 'Election Commission of India', difficulty: 'medium' },
  { slug: 'civ-president-rule-imposed-most-state', categoryId: 'cat-civics', text: 'President\'s Rule (Article 356) has been imposed the most number of times in which Indian state (as of 2024)?', options: ['Bihar', 'Uttar Pradesh', 'Kerala', 'Jammu & Kashmir'], correctIndex: 3, explanation: 'President\'s Rule has been imposed the most in Jammu & Kashmir — over 6 times (before its reorganisation as a UT in 2019). Kerala has had it imposed about 5 times, and Bihar about 8 times. Article 356 allows the President to dismiss a state government and impose direct central rule when constitutional machinery fails. It has been controversially used over 130+ times since 1950.', source: 'Ministry of Home Affairs / Sarkaria Commission Report', difficulty: 'hard' },
  { slug: 'civ-rti-act-cic', categoryId: 'cat-civics', text: 'Under the Right to Information Act, 2005, the Chief Information Commissioner is appointed by whom?', options: ['The President of India', 'The Prime Minister', 'A committee comprising the PM, Leader of Opposition, and a Union Cabinet Minister', 'The Chief Justice of India'], correctIndex: 2, explanation: 'Under Section 12 of the RTI Act, 2005, the Chief Information Commissioner and Information Commissioners are appointed by the President on the recommendation of a committee comprising: the Prime Minister (Chair), the Leader of Opposition in the Lok Sabha, and a Union Cabinet Minister nominated by the PM. The CIC serves a term of 5 years.', source: 'Right to Information Act, 2005, Section 12', difficulty: 'hard' },
  { slug: 'civ-gst-council-establishment-article', categoryId: 'cat-civics', text: 'The GST Council was established by which Constitutional Amendment and under which Article?', options: ['97th Amendment, Article 243Z', '101st Amendment, Article 279A', '103rd Amendment, Article 15(6)', '110th Amendment, Article 243D'], correctIndex: 1, explanation: 'The GST Council was established by the 101st Constitutional Amendment Act, 2016, under Article 279A. The Council is chaired by the Union Finance Minister and includes state finance ministers. It recommends GST rates, exemptions, and thresholds. Decisions require a 3/4 majority, with the Centre having 1/3 votes and States collectively 2/3.', source: 'Constitution of India, Article 279A / 101st Amendment Act, 2016', difficulty: 'medium' },
  { slug: 'civ-rajya-sabha-members-nominated', categoryId: 'cat-civics', text: 'How many members of the Rajya Sabha are nominated by the President of India?', options: ['8', '10', '12', '14'], correctIndex: 2, explanation: 'The President nominates 12 members to the Rajya Sabha from persons having special knowledge or practical experience in: literature, science, art, and social service. The Rajya Sabha has a total strength of 245 (233 elected + 12 nominated). Elected members are chosen by the elected members of State Legislative Assemblies and UT assemblies (Delhi, Puducherry).', source: 'Constitution of India, Article 80', difficulty: 'medium' },
  { slug: 'civ-parliament-sessions-count-india', categoryId: 'cat-civics', text: 'The Indian Parliament normally meets in how many sessions each year?', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 1, explanation: 'The Indian Parliament normally meets in three sessions each year: (1) Budget Session (February-May), the longest; (2) Monsoon Session (July-August); and (3) Winter Session (November-December). The President summons each session. There is no constitutional minimum number of sitting days, though parliamentary committees recommend at least 100 days per year.', source: 'Parliament of India / Lok Sabha Secretariat', difficulty: 'medium' },
  { slug: 'civ-electoral-bonds-scheme-year', categoryId: 'cat-civics', text: 'The Electoral Bonds Scheme was introduced by the Government of India in which year (and was later struck down by the Supreme Court in 2024)?', options: ['2014', '2017', '2019', '2022'], correctIndex: 1, explanation: 'The Electoral Bonds Scheme was introduced on 2 January 2018 (announced in the 2017 Budget). Electoral bonds were interest-free bearer instruments sold by the State Bank of India. On 15 February 2024, the Supreme Court struck down the scheme as unconstitutional, holding it violated the right to information under Article 19(1)(a).', source: 'Supreme Court of India (Association for Democratic Reforms v. Union of India, 2024)', difficulty: 'medium' },

  // ═══ cat-science (10) ═══
  { slug: 'sci-isro-100-launches-sriharikota-count', categoryId: 'cat-science', text: 'ISRO completed how many successful launches from Sriharikota (SDSC SHAR) to reach its 100th mission in 2024?', options: ['75', '90', '100', '120'], correctIndex: 2, explanation: 'ISRO\'s 100th mission from Sriharikota (Satish Dhawan Space Centre) was the PSLV-C60 / SpaDeX mission launched on 30 December 2024. This milestone included launches by SLV, ASLV, PSLV, GSLV, and LVM3 vehicles over 45+ years. The first launch from SHAR was in 1979 (Rohini Technology Payload, SLV-3).', source: 'ISRO official website / Department of Space', difficulty: 'medium' },
  { slug: 'sci-india-first-reactor-name-apsara', categoryId: 'cat-science', text: 'India\'s first nuclear research reactor, commissioned in 1956, was named what?', options: ['CIRUS', 'Dhruva', 'Apsara', 'KAMINI'], correctIndex: 2, explanation: 'Apsara was India\'s first nuclear research reactor, commissioned on 4 August 1956 at BARC, Trombay. It was a swimming pool-type reactor using enriched uranium fuel. It was also Asia\'s first nuclear reactor (outside the USSR). Apsara was decommissioned in 2009 and Apsara-Upgraded was commissioned in 2018.', source: 'Bhabha Atomic Research Centre (BARC) / Department of Atomic Energy', difficulty: 'medium' },
  { slug: 'sci-india-telemedicine-scheme-ayushman', categoryId: 'cat-science', text: 'The eSanjeevani telemedicine platform was launched by the Government of India in which year?', options: ['2015', '2018', '2019', '2021'], correctIndex: 2, explanation: 'eSanjeevani was launched in November 2019 by the Ministry of Health and Family Welfare. It provides two types of telemedicine: patient-to-doctor (eSanjeevani OPD) and doctor-to-doctor (eSanjeevani AB-HWC). By 2024, it had served over 200 million teleconsultations, making it the world\'s largest government telemedicine initiative.', source: 'Ministry of Health and Family Welfare / eSanjeevani', difficulty: 'medium' },
  { slug: 'sci-india-internet-users-penetration-2024', categoryId: 'cat-science', text: 'As of 2024, approximately what percentage of India\'s population uses the internet?', options: ['About 30%', 'About 43%', 'About 52-55%', 'About 75%'], correctIndex: 2, explanation: 'As of 2024, approximately 52-55% of India\'s population (about 750-800 million people) uses the internet. India is the second-largest online market (after China). Jio\'s launch in 2016 dramatically reduced data costs and increased adoption. However, a significant rural-urban digital divide persists. India has over 1.1 billion mobile connections (TRAI).', source: 'TRAI / Ministry of Electronics and IT (MeitY) / IAMAI', difficulty: 'medium' },
  { slug: 'sci-india-semiconductor-fab-tata-2024', categoryId: 'cat-science', text: 'In 2024, which Indian conglomerate received approval to build India\'s first commercial semiconductor fabrication plant?', options: ['Reliance Industries', 'Tata Electronics (in Dholera, Gujarat)', 'Adani Group', 'L&T Semiconductor'], correctIndex: 1, explanation: 'In February 2024, Tata Electronics received approval to build India\'s first commercial semiconductor fabrication plant in Dholera, Gujarat, in partnership with Powerchip Semiconductor Manufacturing Corp (PSMC, Taiwan). The plant will have a capacity of 50,000 wafers per month. The total investment is approximately Rs. 91,000 crore.', source: 'Ministry of Electronics and IT (MeitY) / India Semiconductor Mission', difficulty: 'medium' },
  { slug: 'sci-india-deep-sea-mission-2024', categoryId: 'cat-science', text: 'India\'s Deep Ocean Mission, launched in 2021, aims to send a submersible to what depth in the Indian Ocean?', options: ['1,000 m', '3,000 m', '6,000 m', '10,000 m'], correctIndex: 2, explanation: 'India\'s Deep Ocean Mission (approved in 2021, budget Rs. 4,077 crore) includes the "Samudrayaan" project — a manned submersible named "Matsya6000" designed to reach a depth of 6,000 m in the Indian Ocean. It will carry 3 "aquanauts." If successful, India will join the US, Russia, Japan, France, and China in deep-sea manned exploration.', source: 'Ministry of Earth Sciences / National Institute of Ocean Technology (NIOT)', difficulty: 'hard' },
  { slug: 'sci-india-covid-vaccine-covaxin-developer', categoryId: 'cat-science', text: 'Covaxin, India\'s indigenous COVID-19 vaccine, was developed by Bharat Biotech in collaboration with which institution?', options: ['AIIMS New Delhi', 'Indian Council of Medical Research (ICMR)', 'All India Institute of Medical Sciences', 'National Institute of Virology'], correctIndex: 1, explanation: 'Covaxin was developed by Bharat Biotech (Hyderabad) in collaboration with the Indian Council of Medical Research (ICMR) and the National Institute of Virology (NIV, Pune). It was India\'s first indigenous COVID-19 vaccine, based on an inactivated whole-virion platform. It received emergency use authorization in January 2021.', source: 'ICMR / Bharat Biotech / Ministry of Health', difficulty: 'medium' },
  { slug: 'sci-india-quantum-mission-qubits-target', categoryId: 'cat-science', text: 'Under the National Quantum Mission (approved 2023), India aims to develop quantum computers with how many qubits?', options: ['10-50 qubits', '50-1,000 qubits', '1,000-10,000 qubits', 'Over 1 million qubits'], correctIndex: 1, explanation: 'The National Quantum Mission (approved April 2023, budget Rs. 6,003 crore) aims to develop quantum computers with 50-1,000 physical qubits over 8 years (2023-2031). It also targets quantum communications (satellite-based, 2,000+ km), quantum cryptography, and quantum materials. The mission is led by the Department of Science and Technology (DST).', source: 'Department of Science and Technology (DST), Government of India', difficulty: 'hard' },
  { slug: 'sci-india-drdo-agni-5-range-2024', categoryId: 'cat-science', text: 'The Agni-V missile, successfully tested by DRDO, has an approximate strike range of how many kilometres?', options: ['2,500 km', '3,500 km', '5,000-5,500 km', '8,000 km'], correctIndex: 2, explanation: 'Agni-V has an approximate range of 5,000-5,500 km, classifying it as an Intercontinental Ballistic Missile (ICBM). It is a surface-to-surface, three-stage, solid-fuelled, nuclear-capable missile developed by DRDO. It uses MIRV (Multiple Independently Targetable Re-Entry Vehicle) technology, first tested in March 2024. It can target all of Asia and parts of Europe/Africa.', source: 'DRDO / Ministry of Defence, Government of India', difficulty: 'medium' },
  { slug: 'sci-india-hydrogen-train-trial', categoryId: 'cat-science', text: 'Indian Railways plans to introduce hydrogen-powered trains. The first trial is scheduled for which route?', options: ['Delhi-Agra', 'Jind-Sonipat (Haryana)', 'Mumbai-Pune', 'Chennai-Bangalore'], correctIndex: 1, explanation: 'Indian Railways plans to introduce hydrogen-powered trains (Hydrogen Fuel Cell-based). The first trial run is scheduled on the Jind-Sonipat heritage route in Haryana (89 km). The trains are being developed by Indian Railways in collaboration with Swiss company "Hydrogenics." India aims to be the first country to run a hydrogen-powered train on a broad gauge network.', source: 'Ministry of Railways / Indian Railways Organisation for Alternate Fuels (IROAF)', difficulty: 'hard' },

  // ═══ cat-sports (10) ═══
  { slug: 'spt-india-cricket-test-200-vs-wi', categoryId: 'cat-sports', text: 'Who was the first Indian cricketer to score a triple century (300+) in Test cricket?', options: ['Sunil Gavaskar', 'Virender Sehwag', 'Sachin Tendulkar', 'Rahul Dravid'], correctIndex: 1, explanation: 'Virender Sehwag was the first Indian to score a triple century in Test cricket — 309 against Pakistan at Multan in March 2004 (the "Multan Sultan"). He scored a second triple century (319 vs South Africa at Chennai in 2008). Sehwag is one of only four batsmen to score two Test triple centuries (along with Bradman, Lara, and Gayle).', source: 'ESPN Cricinfo / BCCI / ICC records', difficulty: 'medium' },
  { slug: 'spt-india-olympic-hockey-gold-1936', categoryId: 'cat-sports', text: 'At the 1936 Berlin Olympics, the Indian hockey team won gold. Who scored a hat-trick in the final against Germany?', options: ['Dhyan Chand', 'Roop Singh', 'Ali Dara', 'Joseph Galibardy'], correctIndex: 0, explanation: 'Major Dhyan Chand scored a hat-trick in the 1936 Berlin Olympics hockey final, which India won 8-1 against Germany. Dhyan Chand scored 6 of India\'s 8 goals in that match. Adolf Hitler was so impressed that he reportedly offered Dhyan Chand a commission in the German army, which he declined. Dhyan Chand is widely regarded as the greatest hockey player of all time. His birthday (29 August) is celebrated as National Sports Day.', source: 'International Hockey Federation (FIH) / Indian Olympic Association', difficulty: 'hard' },
  { slug: 'spt-india-badminton-sindhu-world-rank-1', categoryId: 'cat-sports', text: 'PV Sindhu became the first Indian woman badminton player to achieve world No.1 ranking in which year?', options: ['2017', '2019', '2021', '2023'], correctIndex: 1, explanation: 'PV Sindhu became the first Indian woman to achieve world No.1 BWF ranking in April 2019, after winning the BWF World Championships gold in Basel (August 2019). Saina Nehwal had previously reached world No.1 in 2015. Sindhu has won 5 BWF World Championship medals (1 gold, 2 silver, 2 bronze), 2 Olympic medals (silver Rio 2016, bronze Tokyo 2020), and a Commonwealth Games gold.', source: 'Badminton World Federation (BWF)', difficulty: 'medium' },
  { slug: 'spt-india-wrestling-sushil-medal-consecutive', categoryId: 'cat-sports', text: 'Sushil Kumar is the only Indian to win individual Olympic medals at two consecutive Olympics. Which medals did he win?', options: ['Gold (2008) and Gold (2012)', 'Bronze (2008) and Silver (2012)', 'Silver (2008) and Bronze (2012)', 'Bronze (2008) and Bronze (2012)'], correctIndex: 1, explanation: 'Sushil Kumar won bronze (66 kg freestyle wrestling) at the 2008 Beijing Olympics and silver at the 2012 London Olympics — the only Indian to win individual Olympic medals at two consecutive Games. He was India\'s flagbearer at the 2012 Opening Ceremony. He also won gold at the 2010 World Wrestling Championships, becoming India\'s first world champion wrestler.', source: 'International Olympic Committee (IOC) / Wrestling Federation of India', difficulty: 'medium' },
  { slug: 'spt-india-football-sunil-chhetri-debut', categoryId: 'cat-sports', text: 'Sunil Chhetri, India\'s greatest footballer, made his international debut in which year?', options: ['2002', '2005', '2007', '2010'], correctIndex: 1, explanation: 'Sunil Chhetri made his international debut on 12 June 2005 against Pakistan in the AFC Challenge Cup qualifiers (he scored in his debut). He retired in June 2024 with 94 goals in 151 appearances — the 4th-highest in international football history (after Ronaldo, Messi, and Ali Daei). He was awarded the Khel Ratna in 2011 and Padma Shri in 2019.', source: 'All India Football Federation (AIFF) / FIFA', difficulty: 'medium' },
  { slug: 'spt-india-chess-anand-world-champion-years', categoryId: 'cat-sports', text: 'Viswanathan Anand was the undisputed World Chess Champion in which years (combined total)?', options: ['2000-2002 only', '2000, 2007-2008, 2008-2010, 2010-2012', '2007-2013 continuously', '2010-2013 continuously'], correctIndex: 1, explanation: 'Viswanathan Anand was World Chess Champion in: 2000 (FIDE knockout), 2007-2008 (World Championship tournament), 2008-2010 (defeated Kramnik in 2008), 2010-2012 (defeated Topalov in 2010), and 2012-2013 (defeated Gelfand in 2012). He lost the title to Magnus Carlsen in 2013. Anand was India\'s first Grandmaster (1988).', source: 'World Chess Federation (FIDE)', difficulty: 'hard' },
  { slug: 'spt-india-para-athletics-avni-lekha', categoryId: 'cat-sports', text: 'Avani Lekhara became the first Indian woman to win a Paralympic gold medal. At which Paralympics and in what event?', options: ['Rio 2016, 10m air rifle', 'Tokyo 2020 (2021), 10m air rifle standing SH1', 'Paris 2024, 50m rifle 3 positions', 'Tokyo 2020, 50m air rifle prone'], correctIndex: 1, explanation: 'Avani Lekhara won gold in the 10m air rifle standing SH1 event at the Tokyo 2020 Paralympics (held in 2021), becoming the first Indian woman to win a Paralympic gold. She scored 249.6, equalling the Paralympic record. She also won bronze in the 50m rifle 3 positions. At Paris 2024, she defended her gold in the 10m air rifle.', source: 'International Paralympic Committee (IPC) / Paralympic Committee of India', difficulty: 'medium' },
  { slug: 'spt-india-boxing-lovlina-olympic', categoryId: 'cat-sports', text: 'Lovlina Borgohain won India\'s first Olympic boxing medal (bronze) at which Olympics?', options: ['Rio 2016', 'Tokyo 2020 (2021)', 'Paris 2024', 'London 2012'], correctIndex: 1, explanation: 'Lovlina Borgohain won bronze in the 69 kg welterweight boxing event at the Tokyo 2020 Olympics (held in 2021). She was the third Indian boxer to win an Olympic medal, after Vijender Singh (bronze, 2008) and Mary Kom (bronze, 2012). She is from Assam and was awarded the Arjuna Award in 2020 and Padma Shri in 2022.', source: 'International Olympic Committee (IOC) / Boxing Federation of India', difficulty: 'medium' },
  { slug: 'spt-india-table-tennis-sharath-achanta', categoryId: 'cat-sports', text: 'Achanta Sharath Kamal is India\'s most decorated table tennis player. How many Commonwealth Games gold medals has he won (career total)?', options: ['3', '5', '7', '10'], correctIndex: 2, explanation: 'Achanta Sharath Kamal has won 7 Commonwealth Games gold medals (across 2006, 2010, 2018, and 2022). He also won 3 Asian Games medals and 13 national championships. He was awarded the Khel Ratna in 2022 and Padma Shri in 2019. He represented India at 4 Olympics (2004-2020).', source: 'International Table Tennis Federation (ITTF) / Table Tennis Federation of India', difficulty: 'hard' },
  { slug: 'spt-india-cricket-world-cup-1983-opposition-final', categoryId: 'cat-sports', text: 'India won the 1983 Cricket World Cup by defeating which team in the final?', options: ['Australia', 'West Indies', 'England', 'Pakistan'], correctIndex: 1, explanation: 'India defeated the West Indies by 43 runs in the final at Lord\'s on 25 June 1983. India scored 183 all out, then bowled out the West Indies for 140. This was India\'s first Cricket World Cup win. Kapil Dev was captain. The West Indies had won the previous two World Cups (1975, 1979) and were heavy favourites.', source: 'ICC Cricket World Cup records / ESPN Cricinfo', difficulty: 'easy' },

  // ═══ cat-culture (10) ═══
  { slug: 'cul-elephanta-cave-island-location', categoryId: 'cat-culture', text: 'The Elephanta Caves (UNESCO World Heritage Site) are located on an island in which body of water?', options: ['Arabian Sea (near Mumbai)', 'Bay of Bengal (near Chennai)', 'Gulf of Kutch (near Gujarat)', 'Palk Strait (near Rameswaram)'], correctIndex: 0, explanation: 'The Elephanta Caves are on Elephanta Island (Gharapuri, meaning "city of caves") in the Arabian Sea, about 10 km east of Mumbai, Maharashtra. The Portuguese named it "Elephanta" after a large stone elephant found there (now in the Bhau Daji Lad Museum, Mumbai). The caves contain 5th-6th century CE Hindu temples dedicated to Lord Shiva, featuring the famous 20-foot Trimurti sculpture.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'easy' },
  { slug: 'cul-diwali-laxmi-puja-day', categoryId: 'cat-culture', text: 'Diwali, the festival of lights, is celebrated in which Hindu calendar month?', options: ['Chaitra (March-April)', 'Kartika (October-November)', 'Bhadrapada (August-September)', 'Magha (January-February)'], correctIndex: 1, explanation: 'Diwali is celebrated on the new moon day (Amavasya) of the Kartika month (October-November) in the Hindu calendar. It marks the return of Lord Rama to Ayodhya after 14 years of exile. The festival spans 5 days: Dhanteras, Naraka Chaturdashi (Chhoti Diwali), Lakshmi Puja (main Diwali), Govardhan Puja, and Bhai Dooj.', source: 'Ministry of Culture, Government of India', difficulty: 'easy' },
  { slug: 'cul-baisakhi-festival-state', categoryId: 'cat-culture', text: 'Baisakhi (or Vaisakhi), the harvest festival, is primarily associated with which Indian state?', options: ['Rajasthan', 'Punjab', 'Haryana', 'Uttar Pradesh'], correctIndex: 1, explanation: 'Baisakhi is the harvest festival of Punjab, celebrated on 13 or 14 April each year. It marks the start of the solar new year and the rabi harvest. It also commemorates the founding of the Khalsa Panth by Guru Gobind Singh on Baisakhi day in 1699. The festival features Bhangra and Giddha dances and visits to gurdwaras.', source: 'Ministry of Culture / Punjab Tourism', difficulty: 'easy' },
  { slug: 'cul-rath-yatra-jagannath-chariots', categoryId: 'cat-culture', text: 'During the Rath Yatra at Puri, how many chariots are used to carry the deities?', options: ['Two', 'Three (Jagannath, Balabhadra, Subhadra)', 'Four', 'Five'], correctIndex: 1, explanation: 'Three chariots are used in the Puri Rath Yatra: Nandighosha (for Jagannath, 45.6 ft, 18 wheels), Taladhwaja (for Balabhadra, 44 ft, 16 wheels), and Darpadalan (for Subhadra, 43 ft, 14 wheels). Each chariot is newly constructed every year from specific types of wood. The deities are taken from the Jagannath Temple to the Gundicha Temple (about 3 km).', source: 'Jagannath Temple Administration / Department of Tourism, Odisha', difficulty: 'medium' },
  { slug: 'cul-hemis-festival-ladakh', categoryId: 'cat-culture', text: 'The Hemis Festival, celebrating the birth anniversary of Guru Padmasambhava, is held in which region?', options: ['Spiti Valley (Himachal Pradesh)', 'Ladakh (Hemis Monastery)', 'Sikkim', 'Arunachal Pradesh'], correctIndex: 1, explanation: 'The Hemis Festival is held at the Hemis Monastery in Ladakh, usually in June or July. It celebrates the birth anniversary of Guru Padmasambhava (Guru Rinpoche), the founder of Tibetan Buddhism. The festival features masked dances (chhams), traditional music, and the display of the monastery\'s ancient thangkas (rarely shown). Hemis is the largest monastery in Ladakh.', source: 'Ministry of Culture / Leh-Ladakh Tourism', difficulty: 'medium' },
  { slug: 'cul-kathakali-mudras-hand-gestures', categoryId: 'cat-culture', text: 'In Kathakali, the traditional dance-drama from Kerala, how many basic "mudras" (hand gestures) are there in the Hastalakshana Deepika (the gesture text used)?', options: ['12', '18', '24', '36'], correctIndex: 2, explanation: 'Kathakali uses 24 basic mudras (hand gestures) from the "Hastalakshana Deepika," a text specifically used in Kathakali and other Kerala art forms. These mudras can convey hundreds of words and concepts through their combinations. Kathakali also uses elaborate facial expressions (navarasa — nine emotions) and eye movements, all of which take years of training.', source: 'Sangeet Natak Akademi / Kerala Kalamandalam', difficulty: 'hard' },
  { slug: 'cul-modi-script-language', categoryId: 'cat-culture', text: 'The Modi script was historically used to write which language?', options: ['Hindi', 'Marathi', 'Gujarati', 'Bengali'], correctIndex: 1, explanation: 'The Modi script was historically used to write Marathi. It was developed as a cursive script from Devanagari for faster writing, used for court records, correspondence, and administrative documents in the Maratha Empire (17th-19th centuries). It was gradually replaced by Devanagari in the mid-20th century. Efforts are ongoing to preserve Modi script documents, many of which contain historical records of the Maratha Empire.', source: 'Maharashtra State Gazetteer / National Mission for Manuscripts', difficulty: 'medium' },
  { slug: 'cul-onam-boat-race-name', categoryId: 'cat-culture', text: 'The Nehru Trophy Boat Race is held on which lake in Kerala during the Onam festival?', options: ['Vembanad Lake (Punnamada, Alappuzha)', 'Ashtamudi Lake (Kollam)', 'Vellayani Lake (Trivandrum)', 'Sasthamcotta Lake (Kollam)'], correctIndex: 0, explanation: 'The Nehru Trophy Boat Race is held on the Punnamada Lake (part of Vembanad Lake) in Alappuzha (Alleppey), Kerala. It was instituted in 1952 after Jawaharlal Nehru visited Kerala and was impressed by a snake boat race. The race features the Chundan Vallam (snake boat), which is about 100 feet long and carries over 100 rowers. It is held on the second Saturday of August each year.', source: 'Department of Tourism, Kerala', difficulty: 'medium' },
  { slug: 'cul-vaisakhi-khalsa-founding-year', categoryId: 'cat-culture', text: 'The Khalsa Panth (the Sikh order of warrior-saints) was founded by Guru Gobind Singh in which year?', options: ['1574', '1699', '1708', '1764'], correctIndex: 1, explanation: 'Guru Gobind Singh, the 10th Sikh Guru, founded the Khalsa Panth on Baisakhi (13 April) 1699 at Anandpur Sahib, Punjab. He initiated the "Panj Pyare" (Five Beloved Ones) from different castes and regions, establishing the principles of equality, courage, and service. The event marked the formal beginning of the Sikh warrior tradition. The Five Ks (Kesh, Kangha, Kara, Kachera, Kirpan) are symbols of the Khalsa.', source: 'Shiromani Gurdwara Parbandhak Committee (SGPC) / Ministry of Culture', difficulty: 'medium' },
  { slug: 'cul-sangeet-natak-akademi-first-year', categoryId: 'cat-culture', text: 'The Sangeet Natak Akademi, India\'s national academy of music, dance, and drama, was established in which year?', options: ['1947', '1952', '1954', '1962'], correctIndex: 2, explanation: 'The Sangeet Natak Akademi was established on 31 May 1954, as the first national-level academy of arts in India. It is an autonomous body under the Ministry of Culture. It recognises 8 classical dance forms and promotes music, dance, and theatre. The Sangeet Natak Akademi Awards (Akademi Puraskar) are among India\'s most prestigious performing arts awards.', source: 'Sangeet Natak Akademi / Ministry of Culture', difficulty: 'medium' },

  // ═══ cat-economy (10) ═══
  { slug: 'eco-india-gdp-growth-2024-imf', categoryId: 'cat-economy', text: 'India was the fastest-growing major economy in the world in 2023-24. What was its approximate GDP growth rate?', options: ['About 5%', 'About 7-8%', 'About 10%', 'About 12%'], correctIndex: 1, explanation: 'India\'s GDP growth rate in FY 2023-24 was approximately 8.2% (provisional estimates), making India the fastest-growing major economy. The IMF projected India\'s growth at approximately 6.5-7% for 2024-25. India\'s nominal GDP was approximately $3.7 trillion (5th largest globally), projected to become the 3rd largest by 2027-2028.', source: 'International Monetary Fund (IMF) / Ministry of Statistics and Programme Implementation', difficulty: 'medium' },
  { slug: 'eco-india-startup-ecosystem-rank', categoryId: 'cat-economy', text: 'India has the world\'s third-largest startup ecosystem (by number of unicorns). Which two countries are ahead of India?', options: ['USA and UK', 'USA and China', 'China and UK', 'USA and Germany'], correctIndex: 1, explanation: 'India has the world\'s 3rd largest startup ecosystem (by number of unicorns), after the USA and China. India has approximately 100+ unicorns (privately held companies valued at $1 billion+). Bengaluru, Delhi NCR, and Mumbai are the top startup hubs. The "Startup India" initiative was launched on 16 January 2016 to promote entrepreneurship.', source: 'NASSCOM / DPIIT / Startup India', difficulty: 'medium' },
  { slug: 'eco-india-currency-2000-note-withdrawn', categoryId: 'cat-economy', text: 'The Reserve Bank of India announced the withdrawal of the Rs. 2,000 currency note from circulation in which year?', options: ['2018', '2020', '2023', '2024'], correctIndex: 2, explanation: 'On 19 May 2023, the RBI announced the withdrawal of the Rs. 2,000 currency note from circulation. Citizens were given until 7 October 2023 (later extended to 7 April 2024) to deposit or exchange their Rs. 2,000 notes. The note was introduced in November 2016 after demonetisation of Rs. 500 and Rs. 1,000 notes.', source: 'Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-india-fdi-equity-2024-cumulative', categoryId: 'cat-economy', text: 'India\'s cumulative FDI equity inflows from April 2000 to March 2024 are approximately how much?', options: ['About $250 billion', 'About $500 billion', 'About $950+ billion', 'About $1.5 trillion'], correctIndex: 2, explanation: 'India\'s cumulative FDI equity inflows from April 2000 to March 2024 were approximately $950+ billion. The top source countries include Mauritius, Singapore, USA, Netherlands, and Japan. The top sectors include computer software, services, automobiles, and telecommunications. India is one of the top FDI destinations globally.', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / Ministry of Commerce', difficulty: 'medium' },
  { slug: 'eco-india-rbi-currency-note-denominations-2024', categoryId: 'cat-economy', text: 'As of 2024, which is the highest-denomination currency note in circulation in India?', options: ['Rs. 200', 'Rs. 500', 'Rs. 1,000', 'Rs. 2,000'], correctIndex: 1, explanation: 'As of 2024, the highest-denomination currency note in circulation in India is the Rs. 500 note. The Rs. 2,000 note was withdrawn in 2023. The Rs. 1,000 note was demonetised on 8 November 2016. Current notes in circulation: Rs. 10, 20, 50, 100, 200, 500. Coins in circulation: Rs. 1, 2, 5, 10, 20.', source: 'Reserve Bank of India', difficulty: 'easy' },
  { slug: 'eco-india-upi-share-global', categoryId: 'cat-economy', text: 'India\'s UPI accounts for approximately what share of global real-time digital payment transactions?', options: ['About 10%', 'About 25%', 'About 46%', 'About 75%'], correctIndex: 2, explanation: 'India\'s UPI accounts for approximately 46% of all global real-time digital payment transactions. In 2023, India processed approximately 131 billion UPI transactions worth about Rs. 199 lakh crore. UPI was launched in 2016 by the National Payments Corporation of India (NPCI). India has also enabled UPI payments in countries like UAE, Singapore, France, and Bhutan.', source: 'National Payments Corporation of India (NPCI) / RBI / ACI Worldwide', difficulty: 'medium' },
  { slug: 'eco-india-agriculture-employment-share', categoryId: 'cat-economy', text: 'Approximately what percentage of India\'s total workforce is employed in agriculture and allied sectors (as of 2023)?', options: ['About 15%', 'About 25%', 'About 42-46%', 'About 60%'], correctIndex: 2, explanation: 'Approximately 42-46% of India\'s total workforce is employed in agriculture and allied sectors (as of 2023). However, agriculture contributes only about 15-18% of India\'s GDP, indicating low productivity and disguised unemployment. India has the world\'s largest agricultural workforce. The government aims to double farmers\' income and modernise agriculture through technology.', source: 'Ministry of Agriculture / Ministry of Statistics and Programme Implementation (MoSPI)', difficulty: 'medium' },
  { slug: 'eco-india-stock-market-cap-rank', categoryId: 'cat-economy', text: 'As of 2024, India\'s stock market (NSE + BSE combined) is ranked what in the world by market capitalisation?', options: ['3rd', '4th', '5th', '6th'], correctIndex: 2, explanation: 'As of early 2024, India\'s stock market (NSE + BSE combined market capitalisation) is the 5th largest in the world (after USA, China, Japan, and Hong Kong). India surpassed the UK and Saudi Arabia. The BSE Sensex crossed 75,000 points in April 2024. India\'s market capitalisation is approximately $4.5+ trillion.', source: 'World Federation of Exchanges / Securities and Exchange Board of India (SEBI)', difficulty: 'medium' },
  { slug: 'eco-india-renewable-energy-rank', categoryId: 'cat-economy', text: 'India is ranked what in the world for installed renewable energy capacity (as of 2024)?', options: ['2nd', '3rd', '4th', '5th'], correctIndex: 2, explanation: 'India ranks 4th in the world for installed renewable energy capacity (after China, USA, and Brazil, as of 2024). India\'s total installed renewable energy capacity is approximately 180+ GW (including solar ~73 GW, wind ~45 GW, large hydro ~47 GW, and bio-power ~11 GW). India has set a target of 500 GW non-fossil fuel capacity by 2030.', source: 'Ministry of New and Renewable Energy (MNRE) / International Renewable Energy Agency (IRENA)', difficulty: 'medium' },
  { slug: 'eco-india-mobile-manufacturing-export', categoryId: 'cat-economy', text: 'India\'s mobile phone exports grew significantly under the PLI scheme. In FY 2023-24, India\'s mobile phone exports were approximately how much?', options: ['About $5 billion', 'About $10 billion', 'About $15-16 billion', 'About $25 billion'], correctIndex: 2, explanation: 'India\'s mobile phone exports in FY 2023-24 were approximately $15-16 billion, driven by the Production-Linked Incentive (PLI) scheme. Apple and Samsung were the top exporters. India has become the second-largest mobile phone manufacturer in the world (after China). Mobile manufacturing units in India increased from 2 in 2014 to 300+ in 2024.', source: 'Ministry of Electronics and IT (MeitY) / India Cellular and Electronics Association (ICEA)', difficulty: 'medium' },

  // ═══ cat-environment (10) ═══
  { slug: 'env-india-asian-elephant-population', categoryId: 'cat-environment', text: 'India hosts the largest population of Asian elephants in the world. Approximately how many wild elephants does India have (as of the 2017 census)?', options: ['About 10,000', 'About 17,000', 'About 27,000', 'About 40,000'], correctIndex: 2, explanation: 'According to the 2017 elephant census (synchronized elephant estimation), India has approximately 27,312 wild Asian elephants — the largest population in the world. Karnataka has the most elephants (6,049), followed by Assam (5,719) and Kerala (3,054). Project Elephant was launched in 1992 to conserve elephants and their habitat.', source: 'Ministry of Environment, Forest and Climate Change / Project Elephant', difficulty: 'medium' },
  { slug: 'env-india-gharial-croc-critically', categoryId: 'cat-environment', text: 'The gharial (Gavialis gangeticus), a critically endangered crocodilian, is native to which river system in India?', options: ['Ganga and Yamuna rivers', 'Ganga-Brahmaputra-Mahanadi river system', 'Narmada and Tapti rivers', 'Godavari and Krishna rivers'], correctIndex: 1, explanation: 'The gharial (Gavialis gangeticus), one of the most critically endangered crocodilians in the world, is native to the Ganga-Brahmaputra-Mahanadi river system in India and Nepal. It is recognised by its long, slender snout (ghara — meaning "mud pot" — in adult males). The wild population is estimated at fewer than 1,000 individuals. The Kukrail Gharial Rehabilitation Centre in Lucknow breeds gharials for release.', source: 'IUCN Red List / Ministry of Environment, Forest and Climate Change / Wildlife Institute of India', difficulty: 'hard' },
  { slug: 'env-india-clean-river-namami-gange-impact', categoryId: 'cat-environment', text: 'The Namami Gange programme has led to a significant increase in which aquatic species in the Ganga river?', options: ['Gangetic dolphins', 'Hilsa fish (and Gangetic dolphins)', 'Gharials only', 'Sawan fish'], correctIndex: 1, explanation: 'The Namami Gange programme has led to a significant increase in both Hilsa fish (Tenualosa ilisha) and Gangetic dolphins in the Ganga. The dolphin population in the Ganga increased from about 2,000 in 2015 to approximately 4,000+ (2023 survey, including tributaries). Hilsa fish catch has also increased due to improved water flow and reduced pollution. The Gangetic dolphin is India\'s national aquatic animal.', source: 'National Mission for Clean Ganga (NMCG) / Wildlife Institute of India', difficulty: 'hard' },
  { slug: 'env-india-mangrove-area-increase', categoryId: 'cat-environment', text: 'According to the India State of Forest Report 2021, India\'s mangrove cover increased by how many sq km compared to the 2019 assessment?', options: ['Decreased by 5 sq km', 'Increased by 17 sq km', 'Increased by 50 sq km', 'Increased by 100 sq km'], correctIndex: 1, explanation: 'According to the India State of Forest Report 2021, India\'s mangrove cover increased by 17 sq km (from 4,975 sq km in 2019 to 4,992 sq km in 2021). The largest mangrove cover is in West Bengal (2,114 sq km, Sundarbans), followed by Gujarat (1,222 sq km). Mangroves are crucial for coastal protection, carbon sequestration, and biodiversity.', source: 'Forest Survey of India, Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-india-vulture-decline-diclofenac', categoryId: 'cat-environment', text: 'The dramatic decline of vulture populations in India in the 1990s-2000s was primarily caused by what?', options: ['Habitat loss', 'Diclofenac poisoning (veterinary drug in livestock carcasses)', 'Avian flu', 'Pesticide poisoning'], correctIndex: 1, explanation: 'The primary cause of the vulture population crash (90-99% decline in some species) in India was diclofenac — a veterinary anti-inflammatory drug given to livestock. When vultures consumed carcasses of diclofenac-treated livestock, they suffered kidney failure and died. India banned veterinary use of diclofenac in 2006. Three critically endangered vulture species affected: White-rumped, Indian, and Slender-billed vultures.', source: 'IUCN Red List / Ministry of Environment / Bombay Natural History Society (BNHS)', difficulty: 'hard' },
  { slug: 'env-india-tiger-census-camera-trap-method', categoryId: 'cat-environment', text: 'India\'s tiger census uses camera trapping for individual identification. What unique physical feature is used to identify each tiger?', options: ['Facial markings', 'Paw prints (pugmarks)', 'Stripe patterns on the body', 'Eye colour'], correctIndex: 2, explanation: 'India\'s tiger census uses camera trapping to identify individual tigers by their unique stripe patterns — similar to fingerprints in humans. No two tigers have the same stripe pattern. This method, used since 2006, replaced the earlier pugmark census method which was less accurate. The 2022 census estimated 3,167 tigers using about 32,000 camera traps across 77,000 sq km of tiger-bearing forests.', source: 'National Tiger Conservation Authority (NTCA) / Wildlife Institute of India', difficulty: 'medium' },
  { slug: 'env-india-biodiversity-hotspots', categoryId: 'cat-environment', text: 'India contains how many of the world\'s 36 biodiversity hotspots?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 3, explanation: 'India contains 4 of the world\'s 36 biodiversity hotspots: (1) Western Ghats (Sri Lanka and Western Ghats), (2) Himalaya (Eastern Himalaya), (3) Indo-Burma (Northeast India), and (4) Sundaland (Nicobar Islands). Biodiversity hotspots are regions with exceptionally high species endemism that are also heavily threatened by human activities. India is one of the world\'s 17 megadiverse countries.', source: 'Conservation International / Ministry of Environment, Forest and Climate Change', difficulty: 'hard' },
  { slug: 'env-india-renewable-target-2030-500gw', categoryId: 'cat-environment', text: 'India has committed to installing how much non-fossil fuel energy capacity by 2030 (announced at COP26, 2021)?', options: ['175 GW', '250 GW', '500 GW', '750 GW'], correctIndex: 2, explanation: 'At COP26 in Glasgow (2021), India committed to installing 500 GW of non-fossil fuel energy capacity by 2030 (as part of "Panchamrit" — five climate commitments). This includes solar, wind, hydro, and nuclear. India also committed to: 50% energy from renewables by 2030, 1 billion tonnes CO2 reduction by 2030, 45% carbon intensity reduction by 2030, and net zero by 2070.', source: 'UNFCCC COP26 / Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-india-wildlife-institute', categoryId: 'cat-environment', text: 'The Wildlife Institute of India (WII), a premier institution for wildlife research and training, is located in which city?', options: ['Bengaluru', 'Dehradun', 'Delhi', 'Bhopal'], correctIndex: 1, explanation: 'The Wildlife Institute of India (WII) is located in Dehradun, Uttarakhand. It was established in 1982 as an autonomous institution under the Ministry of Environment, Forest and Climate Change. WII conducts wildlife research, training of forest officers, and biodiversity assessments. It plays a key role in India\'s tiger census, elephant census, and snow leopard surveys.', source: 'Wildlife Institute of India / Ministry of Environment, Forest and Climate Change', difficulty: 'medium' },
  { slug: 'env-india-cop28-climate-finance', categoryId: 'cat-environment', text: 'At COP28 (2023), India advocated for climate finance commitments from developed countries. What was the target amount for climate finance to developing countries?', options: ['$10 billion annually', '$50 billion annually', '$100 billion annually (originally committed at COP15, 2009)', '$500 billion annually'], correctIndex: 2, explanation: 'At COP28, India reiterated the demand for developed countries to meet their 2009 commitment of $100 billion annually in climate finance for developing countries (originally promised at COP15, Copenhagen, 2009). This target was finally met in 2022 (3 years late). India also emphasized the need for technology transfer, climate adaptation finance, and the principle of Common but Differentiated Responsibilities (CBDR).', source: 'UNFCCC COP28 / Ministry of Environment, Forest and Climate Change', difficulty: 'hard' },

  // ═══ cat-art (10) ═══
  { slug: 'art-kutub-minar-construction-start', categoryId: 'cat-art', text: 'Construction of the Qutub Minar was begun by Qutb-ud-din Aibak and completed by which ruler?', options: ['Razia Sultana', 'Iltutmish', 'Alauddin Khalji', 'Firoz Shah Tughlaq'], correctIndex: 1, explanation: 'Construction of the Qutub Minar was begun by Qutb-ud-din Aibak in 1199 but was completed by his son-in-law Iltutmish in 1220. Firoz Shah Tughlaq later repaired the top two floors after lightning damage in 1368. At 73 m (239 ft), it is the tallest brick minaret in the world and is a UNESCO World Heritage Site, part of the Qutub Complex in Delhi.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'art-classical-music-bhatkhande-thaat', categoryId: 'cat-art', text: 'The 10 thaats (parent scales) of Hindustani classical music were systematised by whom?', options: ['Pandit Vishnu Narayan Bhatkhande', 'Pandit Vishnu Digambar Paluskar', 'Ustad Alladiya Khan', 'Ustad Amir Khan'], correctIndex: 0, explanation: 'The 10 thaats (parent scales) of Hindustani classical music were systematised by Pandit Vishnu Narayan Bhatkhande (1860-1936) in the early 20th century. The 10 thaats are: Bilawal, Kalyan, Khamaj, Bhairav, Poorvi, Marwa, Kafi, Asavari, Bhairavi, and Todi. Bhatkhande was a musicologist who travelled across India collecting and classifying Hindustani ragas.', source: 'Sangeet Natak Akademi / ITC Sangeet Research Academy', difficulty: 'hard' },
  { slug: 'art-indian-cinema-first-talkie', categoryId: 'cat-art', text: 'India\'s first "talkie" (film with synchronised sound) was released in 1931. What was its name?', options: ['Raja Harishchandra (1913)', 'Alam Ara (1931)', 'Kisan Kanya (1937)', 'Mother India (1957)'], correctIndex: 1, explanation: '"Alam Ara" (The Light of the World), directed by Ardeshir Irani, was India\'s first talkie, released on 14 March 1931 at the Majestic Cinema in Bombay. It was a Hindi-Urdu film. India\'s first feature film (silent) was "Raja Harishchandra" (1913) by Dadasaheb Phalke. No copies of Alam Ara survive — it is considered a lost film.', source: 'National Film Archive of India (NFAI) / Ministry of Information and Broadcasting', difficulty: 'medium' },
  { slug: 'art-bharat-shreshtha-bharat-diverse', categoryId: 'cat-art', text: 'India has 22 scheduled languages (8th Schedule). Which language has the most speakers in India (as a first language, per 2011 Census)?', options: ['Bengali', 'Hindi', 'Telugu', 'Marathi'], correctIndex: 1, explanation: 'Hindi is the most spoken language in India as a first language, with approximately 43.6% of the population (about 528 million people, per the 2011 Census). Bengali is second (~8.3%), followed by Marathi (~6.9%), Telugu (~6.7%), and Tamil (~5.9%). The 8th Schedule lists 22 scheduled languages. India has 121 languages with 10,000+ speakers and over 19,500 mother tongues (2011 Census).', source: 'Census of India 2011 / Registrar General of India', difficulty: 'medium' },
  { slug: 'art-rabindranath-tagore-gitanjali-original', categoryId: 'cat-art', text: 'The original Bengali "Gitanjali" was published in which year, and the English translation was published in which year?', options: ['1910 (Bengali), 1912 (English)', '1912 (Bengali), 1913 (English)', '1905 (Bengali), 1908 (English)', '1913 (Bengali), 1913 (English)'], correctIndex: 0, explanation: 'The original Bengali "Gitanjali" (Song Offerings) was published in 1910. The English translation (by Tagore himself) was published in 1912. Tagore received the Nobel Prize in Literature in 1913 — the first Asian to receive a Nobel. The English version contains 157 poems (53 from the original Bengali Gitanjali + 104 from other Bengali collections).', source: 'Nobel Prize Foundation / Visva-Bharati University', difficulty: 'hard' },
  { slug: 'art-madhubani-painting-gi-tag', categoryId: 'cat-art', text: 'Madhubani painting received a Geographical Indication (GI) tag. In which state does this art form originate?', options: ['Uttar Pradesh', 'Bihar', 'Jharkhand', 'West Bengal'], correctIndex: 1, explanation: 'Madhubani painting (Mithila painting) originates from the Mithila region of Bihar, particularly the Madhubani district. It was traditionally created by women on walls and floors for festivals and weddings. The art uses natural dyes and pigments and features geometric patterns, deities, and nature motifs. It received GI (Geographical Indication) tag status in 2007.', source: 'Ministry of Culture / Geographical Indications Registry, Chennai', difficulty: 'medium' },
  { slug: 'art-indian-classical-dance-odissi-origin', categoryId: 'cat-art', text: 'Odissi, one of the 8 classical dance forms of India, traces its origins to which state and ancient text?', options: ['Kerala and the Natya Shastra', 'Odisha and the Natya Shastra (with the Gotipua and Mahari traditions)', 'Tamil Nadu and the Silappadikaram', 'Karnataka and the Natya Shastra'], correctIndex: 1, explanation: 'Odissi originates from Odisha and traces its roots to the Natya Shastra (c. 200 BCE - 200 CE). It evolved from the Mahari tradition (temple dancers) and the Gotipua tradition (boys dressed as girls performing acrobatic dances). The earliest evidence of Odissi is found in the sculptures of the Udayagiri and Khandagiri caves (2nd century BCE) near Bhubaneswar.', source: 'Sangeet Natak Akademi / Odisha Tourism', difficulty: 'hard' },
  { slug: 'art-mughal-miniature-akbar-workshop', categoryId: 'cat-art', text: 'Emperor Akbar established a royal painting workshop (karkhana) at which location?', options: ['Delhi', 'Fatehpur Sikri', 'Agra Fort', 'Lahore'], correctIndex: 1, explanation: 'Emperor Akbar established a royal painting workshop (karkhana) at Fatehpur Sikri, his capital (1571-1585). The workshop employed over 100 artists, including Persian masters like Mir Sayyid Ali and Abdus Samad, and Indian artists. This fusion produced the distinctive Mughal miniature painting style. Key works produced include the Hamzanama (c. 1,400 paintings on cloth).', source: 'National Museum, New Delhi / Archaeological Survey of India', difficulty: 'hard' },
  { slug: 'art-indian-architecture-gopuram-feature', categoryId: 'cat-art', text: 'The "gopuram" is a prominent architectural feature of temples in which Indian state/region?', options: ['North India (Khajuraho temples)', 'South India (Tamil Nadu, Andhra Pradesh, Kerala, Karnataka)', 'East India (Odisha temples)', 'West India (Gujarat temples)'], correctIndex: 1, explanation: 'The "gopuram" (or gopura) is a monumental tower at the entrance gate of South Indian temples, particularly in Tamil Nadu, Andhra Pradesh, Kerala, and Karnataka. It is a pyramidal structure covered with elaborate sculptures of deities, mythological scenes, and animals. The tallest gopuram is at the Ranganathaswamy Temple, Srirangam (72 m / 237 ft, 13 tiers). The Meenakshi Amman Temple in Madurai has 14 gopurams.', source: 'Archaeological Survey of India / Tamil Nadu Tourism', difficulty: 'medium' },
  { slug: 'art-indian-music-tala-teental-beats', categoryId: 'cat-art', text: 'The most common tala (rhythmic cycle) in Hindustani classical music is "Teental." How many beats (matras) does it contain?', options: ['8 beats', '12 beats', '16 beats (4+4+4+4)', '24 beats'], correctIndex: 2, explanation: 'Teental (also spelled Trital) contains 16 beats (matras) divided into 4 equal sections (vibhags) of 4 beats each: 4+4+4+4. It is the most common tala in Hindustani classical music. Theka (basic pattern): Dha Dhin Dhin Dha | Dha Dhin Dhin Dha | Dha Tin Tin Ta | Ta Dhin Dhin Dha. Other common talas: Ektaal (12 beats), Jhaptaal (10 beats), Rupak (7 beats).', source: 'Sangeet Natak Akademi / ITC Sangeet Research Academy', difficulty: 'hard' },

  // ═══ cat-edu (10) ═══
  { slug: 'edu-india-literacy-rate-2024-census', categoryId: 'cat-edu', text: 'According to the 2011 Census, India\'s literacy rate was approximately 74%. What was the gap between male and female literacy rates?', options: ['About 5%', 'About 10%', 'About 16.7% (82.1% male vs 65.5% female)', 'About 25%'], correctIndex: 2, explanation: 'According to the 2011 Census, India\'s literacy rate was 74.04% — male literacy was 82.14% and female literacy was 65.46%, a gap of about 16.7 percentage points. The gap was wider in rural areas. Kerala has the highest literacy rate (94%), and Bihar has the lowest (63.8%). The 2021 Census (delayed) is expected to show improvement.', source: 'Census of India 2011 / Registrar General of India', difficulty: 'medium' },
  { slug: 'edu-india-ger-higher-education-2024', categoryId: 'cat-edu', text: 'India\'s Gross Enrolment Ratio (GER) in higher education was approximately what percentage as of 2022-23 (AISHE report)?', options: ['About 15%', 'About 24%', 'About 28.4%', 'About 45%'], correctIndex: 2, explanation: 'India\'s GER in higher education was approximately 28.4% as of 2021-22 (AISHE report, released 2023). This means about 28.4% of the 18-23 age group is enrolled in higher education. NEP 2020 targets 50% GER by 2035. The male GER is about 28.5% and female GER is about 28.2%, showing near gender parity at the national level.', source: 'All India Survey on Higher Education (AISHE) / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-india-rte-25-percent-implementation', categoryId: 'cat-edu', text: 'Under the RTE Act, 2009 (Section 12(1)(c)), private unaided schools must reserve 25% of entry-level seats for children from which groups?', options: ['Only SC/ST children', 'Only girls from BPL families', 'Disadvantaged and Economically Weaker Section (EWS) groups', 'Children of armed forces personnel'], correctIndex: 2, explanation: 'Under Section 12(1)(c) of the RTE Act, 2009, all private unaided schools must reserve 25% of entry-level seats (Class 1 or pre-primary) for children from "disadvantaged" and "EWS" groups. The government reimburses the tuition fees for these children. States define "disadvantaged" and "EWS" categories differently. Implementation varies widely across states.', source: 'Ministry of Education / RTE Act, 2009, Section 12(1)(c)', difficulty: 'medium' },
  { slug: 'edu-india-national-literacy-mission-origin', categoryId: 'cat-edu', text: 'The National Literacy Mission (NLM) was launched in India in which year?', options: ['1982', '1986', '1988', '1992'], correctIndex: 2, explanation: 'The National Literacy Mission was launched on 5 May 1988. It aimed to impart functional literacy to non-literate adults (15-35 age group). The NLM was merged with the Saakshar Bharat programme in 2009. Saakshar Bharat was launched on 8 September 2009 (International Literacy Day) and focuses on female literacy in rural areas.', source: 'Ministry of Education / National Literacy Mission Authority', difficulty: 'medium' },
  { slug: 'edu-india-kendriya-vidyalaya-count-2024', categoryId: 'cat-edu', text: 'As of 2024, approximately how many Kendriya Vidyalayas (KVs) are operational in India?', options: ['About 500', 'About 1,000', 'About 1,255', 'About 1,500'], correctIndex: 2, explanation: 'As of 2024, approximately 1,255 Kendriya Vidyalayas are operational across India (and abroad). KVs are central government schools under the Kendriya Vidyalaya Sangathan (KVS), established on 15 December 1963. They primarily serve children of transferable Central Government employees, including Defence and PSU personnel. KVs follow the CBSE curriculum.', source: 'Kendriya Vidyalaya Sangathan (KVS) / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-india-aiims-first-established', categoryId: 'cat-edu', text: 'AIIMS New Delhi was established under which Act of Parliament?', options: ['AIIMS Act, 1952', 'AIIMS Act, 1956', 'AIIMS Act, 1960', 'AIIMS Act, 1966'], correctIndex: 1, explanation: 'AIIMS New Delhi was established under the All India Institute of Medical Sciences Act, 1956. It was inaugurated in 1960 and is India\'s top-ranked medical institution. The AIIMS Act was amended in 2012 to allow establishment of new AIIMS as "Institutes of National Importance." As of 2024, there are 22+ AIIMS sanctioned (including New Delhi), most under the PMSSY scheme.', source: 'AIIMS New Delhi / Ministry of Health and Family Welfare / AIIMS Act, 1956', difficulty: 'medium' },
  { slug: 'edu-india-nirf-ranking-topper-2024', categoryId: 'cat-edu', text: 'In the National Institutional Ranking Framework (NIRF) 2024 rankings, which institution was ranked first overall in India?', options: ['IISc Bengaluru', 'IIT Madras', 'IIT Delhi', 'IIT Bombay'], correctIndex: 1, explanation: 'In NIRF 2024, IIT Madras was ranked first overall in India for the 6th consecutive year. NIRF was launched in 2015 (first rankings in 2016). NIRF ranks institutions based on: Teaching, Learning & Resources (TLR), Research and Professional Practice (RP), Graduation Outcomes (GO), Outreach and Inclusivity (OI), and Peer Perception. NIRF covers categories including Overall, Engineering, Management, Medical, Law, and more.', source: 'Ministry of Education / NIRF official website', difficulty: 'medium' },
  { slug: 'edu-india-digi-locker-use-cases', categoryId: 'cat-edu', text: 'DigiLocker, the Government of India\'s digital document wallet, stores which types of documents?', options: ['Only Aadhaar cards', 'Only driving licences', 'Government-issued documents including Aadhaar, driving licence, vehicle RC, educational certificates, vaccination certificates, and more', 'Only income tax returns'], correctIndex: 2, explanation: 'DigiLocker stores a wide range of government-issued documents including: Aadhaar, driving licence, vehicle Registration Certificate (RC), CBSE/State Board educational certificates, Class 10/12 marksheets, CBSE results, COVID-19 vaccination certificates, insurance policies, PAN card, and more. By 2024, DigiLocker had 270+ million users and 6+ billion documents. Documents in DigiLocker are legally equivalent to originals under the IT Act, 2000.', source: 'Ministry of Electronics and IT (MeitY) / NeGD / DigiLocker', difficulty: 'easy' },
  { slug: 'edu-india-national-medical-commission', categoryId: 'cat-edu', text: 'The National Medical Commission (NMC) replaced which former regulatory body for medical education in India?', options: ['University Grants Commission (UGC)', 'Medical Council of India (MCI)', 'All India Council for Technical Education (AICTE)', 'Dental Council of India (DCI)'], correctIndex: 1, explanation: 'The National Medical Commission (NMC) replaced the Medical Council of India (MCI) on 25 September 2020, under the NMC Act, 2019. The NMC regulates medical education, practice, and ethics in India. It comprises 4 autonomous boards: UG Medical Education, PG Medical Education, Medical Assessment and Rating, and Ethics and Medical Registration. The MCI was established in 1933 and dissolved amid corruption allegations.', source: 'National Medical Commission / Ministry of Health and Family Welfare', difficulty: 'medium' },
  { slug: 'edu-india-ncert-textbook-adoption', categoryId: 'cat-edu', text: 'NCERT textbooks are used by which category of schools in India?', options: ['Only by CBSE-affiliated schools', 'By CBSE schools, many state boards, and as reference by other boards', 'Only by private schools', 'Only by Kendriya Vidyalayas'], correctIndex: 1, explanation: 'NCERT textbooks are used by: all CBSE-affiliated schools (~28,000+ schools), Kendriya Vidyalayas, Jawahar Navodaya Vidyalayas, and many state government schools (20+ states have adopted/adapted NCERT textbooks). NCERT develops textbooks for Classes 1-12. The National Curriculum Framework (NCF) guides NCERT textbook development. NCERT was established on 1 September 1961.', source: 'NCERT / Ministry of Education', difficulty: 'medium' },
];

async function main() {
  console.log('=== Batch 7 Import ===\n');
  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing: ${existing.length}, Batch: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy','medium','hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) errors.push(`exact duplicate: ${dupResult.reason}`);
    else if (dupResult.isNearDuplicate) warnings.push(`near-duplicate: ${dupResult.reason}`);

    if (errors.length > 0) { rejected++; rejections.push({ slug: q.slug, errors }); continue; }
    if (warnings.length > 0) { warned++; warningsLog.push({ slug: q.slug, warnings }); }

    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug, categoryId: q.categoryId, text: q.text.trim(), translations: '{}',
          options: JSON.stringify(options), correctOptionIndex: q.correctIndex,
          explanation: q.explanation.trim(), explanationTranslations: '{}',
          source: q.source.trim(), difficulty: q.difficulty, language: 'en', published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped: ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings: ${warned}`);
  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
